// Lumenmorph and Slidebox are loaded for this playground.
const { trackPointer, enhanceSlideboxRange, enhanceSlideboxRangeFill } =
  LumenExample;
const controller = new AbortController();
const stopLight = trackPointer(document.querySelector(".lm-lab"));
const ranges = [...document.querySelectorAll("input[type=range]")].flatMap(
  (input) => [enhanceSlideboxRange(input), enhanceSlideboxRangeFill(input)],
);

(function (demo, signal) {
  const input = demo.querySelector("[data-warmth]");
  const render = () => {
    const value = Number(input.value);
    demo.querySelector("output").textContent = `${value}°`;
    demo.querySelector(".climate-face span").textContent =
      value < 21
        ? "a little cooler"
        : value > 24
          ? "warm & cozy"
          : "just right";
    const progress = (value - 16) / 14;
    const stops = [
      [126, 196, 255],
      [112, 213, 197],
      [255, 170, 113],
    ];
    const half = progress < 0.5 ? 0 : 1;
    const blend = progress < 0.5 ? progress * 2 : (progress - 0.5) * 2;
    const color = stops[half].map((channel, index) =>
      Math.round(channel + (stops[half + 1][index] - channel) * blend),
    );
    demo.style.setProperty("--temperature-color", `rgb(${color.join(" ")})`);
    demo.style.setProperty(
      "--temperature-tint",
      `rgb(${color.join(" ")} / .16)`,
    );
    demo.style.setProperty("--warmth", `${progress * 75}%`);
    input.setAttribute("aria-valuetext", `${value} degrees Celsius`);
  };
  input.addEventListener("input", render, { signal });
  render();
})(document.querySelector(".showcase-demo"), controller.signal);

window.addEventListener("pagehide", (event) => {
  if (!event.persisted) {
    controller.abort();
    stopLight();
    ranges.forEach((stop) => stop());
  }
});
